-- C12 / P12.2 — shopping specialist truth, timing semantics, trip priorities, provider evidence, and privacy.
create table if not exists public.command_center_shopping_offer_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 offer_event_id text not null check(btrim(offer_event_id)<>''), offer_id text not null check(btrim(offer_id)<>''), provider_key text not null check(btrim(provider_key)<>''), merchant_ref text not null check(btrim(merchant_ref)<>''), item_ref text not null check(btrim(item_ref)<>''), amount numeric not null check(amount>=0), timing text not null check(timing in ('immediate','delayed_rebate','cashback')), truth text not null check(truth in ('verified','estimated','stale','unavailable')), truth_owner text not null default 'specialist:shopping' check(truth_owner='specialist:shopping'), privacy_class text not null default 'personal_family' check(privacy_class='personal_family'), source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null, expires_at timestamptz,
 primary key(owner_id,offer_event_id), unique(owner_id,offer_id,observed_at), check(expires_at is null or expires_at>=observed_at)
);
create table if not exists public.command_center_shopping_trip_assessment_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 assessment_event_id text not null check(btrim(assessment_event_id)<>''), merchant_ref text not null check(btrim(merchant_ref)<>''), priority text not null check(priority in ('preserve_cash_today','lowest_final_cost','closest_practical')), out_of_pocket_today numeric not null check(out_of_pocket_today>=0), delayed_savings numeric not null check(delayed_savings>=0), effective_final_cost numeric not null check(effective_final_cost>=0), travel_minutes numeric check(travel_minutes is null or travel_minutes>=0), evidence_refs text[] not null default '{}'::text[], observed_at timestamptz not null,
 primary key(owner_id,assessment_event_id),
 check(priority<>'closest_practical' or travel_minutes is not null)
);
create or replace function public.command_center_reject_shopping_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Shopping evidence is immutable'; end $$;
drop trigger if exists command_center_shopping_offer_immutable on public.command_center_shopping_offer_history; create trigger command_center_shopping_offer_immutable before update or delete on public.command_center_shopping_offer_history for each row execute function public.command_center_reject_shopping_evidence_mutation();
drop trigger if exists command_center_shopping_trip_immutable on public.command_center_shopping_trip_assessment_history; create trigger command_center_shopping_trip_immutable before update or delete on public.command_center_shopping_trip_assessment_history for each row execute function public.command_center_reject_shopping_evidence_mutation();
alter table public.command_center_shopping_offer_history enable row level security; alter table public.command_center_shopping_trip_assessment_history enable row level security;
revoke all on table public.command_center_shopping_offer_history,public.command_center_shopping_trip_assessment_history from public,anon,authenticated; grant select,insert on table public.command_center_shopping_offer_history,public.command_center_shopping_trip_assessment_history to authenticated;
create policy p12_2_shopping_offer_owner on public.command_center_shopping_offer_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()) and truth_owner='specialist:shopping' and privacy_class='personal_family');
create policy p12_2_shopping_trip_owner on public.command_center_shopping_trip_assessment_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
